```js
async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const raf = () => new Promise((r) => requestAnimationFrame(() => r(performance.now())));
  const inPool = (node) => (node instanceof Element ? node : node.parentElement)?.closest(".db-pool") != null;
  let lastAny = 0, lastTree = 0;
  new MutationObserver((records) => {
    const now = performance.now();
    for (const r of records) if (inPool(r.target) && !(r.target instanceof Element && r.target.closest(".cf-art"))) { lastAny = now; if (r.type === "childList") lastTree = now; }
  }).observe(document.body, { subtree: true, childList: true, attributes: true, characterData: true });
  const cards = () => document.querySelectorAll(".db-pool .db-card").length;
  const watch = async (t0) => {
    lastAny = lastTree = t0;
    const timeline = [];
    while (performance.now() - Math.max(lastAny, t0) < 1000) timeline.push([await raf(), cards()]);
    const n = cards();
    const at = (pred) => { const hit = timeline.find(([, c]) => pred(c)); return hit ? Math.round(hit[0] - t0) : null; };
    const whole = at((c) => c === n);
    return { n, first: at((c) => c > 0), whole, tree: Math.round(Math.max(lastTree - t0, whole)), settled: Math.round(Math.max(lastAny - t0, whole)) };
  };
  const out = {};
  history.pushState(null, "", "/almanac"); let t0 = performance.now(); dispatchEvent(new PopStateEvent("popstate"));
  out.open = await watch(t0);
  const input = document.querySelector('[data-testid="db-search"]');
  const type = (v) => { Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set.call(input, v); input.dispatchEvent(new Event("input", { bubbles: true })); };
  type("bigot"); t0 = performance.now(); out.search = await watch(t0);
  type(""); t0 = performance.now(); out.clear = await watch(t0);
  const scroller = document.querySelector(".db-pool");
  scroller.scrollTop = 0; await sleep(500); await raf();
  const frames = []; let prev = await raf();
  for (let i = 0; i < 80; i++) { scroller.scrollTop += 240; const t = await raf(); frames.push(t - prev); prev = t; }
  frames.sort((a, b) => a - b);
  out.scroll = { mean: Math.round(frames.reduce((a, b) => a + b, 0) / frames.length), p95: Math.round(frames[Math.floor(frames.length * 0.95)]) };
